	error_reporting(0);	
				
	$ConfigData		= file_get_contents("../Includes/Configure.php");

	$PosA = strpos($ConfigData, '$RotateArticles', 1);
	$PosA = strpos($ConfigData, chr(34), $PosA) + 1;	
	$PosB = strpos($ConfigData, chr(34), $PosA);
	
	$RotateArticles = substr($ConfigData, $PosA, $PosB - $PosA);  
					
	if($RotateArticles != "")
		{								
			$dirList					= opendir(getcwd());  	
			$arrList					= array(); 				
			
			while (($dirPart			= @readdir($dirList)) == true) 
				{  			
					if (substr($dirPart, (strlen($dirPart) -4), 4) == ".php")	
						{
							$arrList[]	= $dirPart; 
						}
				} 	
			
			$rndKey						= rand(0,sizeof($arrList)-1); 	
			
			header("Location: ".$arrList[$rndKey]);
		}
	else
		{
			$PosA = strpos($ConfigData, '$HomePage', 1);
			$PosA = strpos($ConfigData, chr(34), $PosA) + 1;	
			$PosB = strpos($ConfigData, chr(34), $PosA);
			
			$HomePage = substr($ConfigData, $PosA, $PosB - $PosA);  

			header("Location: ../Articles/".$HomePage);
		}
?>
